// NASA NSSDCA mean dimensions/distances/periods. Illustrative phases, circular coplanar orbits.
export const SOLAR_KM_PER_R=1000000,AU_KM=149597870.7,SOLAR_SECONDS_PER_UNIT=SOLAR_KM_PER_R/299792.458;
export const solarBodies=[{name:'Sun',radius:.6957,position:[0,0,0],color:[1,.67,.2],omega:0},...[['Mercury',4879,57.9,.9,88,[.57,.52,.46]],['Venus',12104,108.2,-.65,224.7,[.92,.73,.4]],['Earth',12756,149.6,0,365.2,[.18,.48,.85]],['Mars',6792,228,.65,687,[.8,.32,.18]],['Jupiter',142984,778.5,-.4,4331,[.8,.65,.48]],['Saturn',120536,1432,.5,10747,[.84,.76,.52]],['Uranus',51118,2867,-.6,30589,[.42,.8,.83]],['Neptune',49528,4515,.35,59800,[.21,.39,.9]]].map(([name,diameter,orbit,phase,days,color])=>({name,radius:diameter/2/SOLAR_KM_PER_R,orbit,phase,color,omega:2*Math.PI*SOLAR_SECONDS_PER_UNIT/(days*86400),position:[Math.sin(phase)*orbit,0,Math.cos(phase)*orbit]}))];
export function solarSnapshot(time=0){return solarBodies.map(b=>{const a=(b.phase??0)+b.omega*time,position=b.orbit?[Math.sin(a)*b.orbit,0,Math.cos(a)*b.orbit]:[0,0,0];return{...b,position,velocity:[b.omega*position[2],0,-b.omega*position[0]]};});}
function local(d,yaw,pitch){const x=Math.cos(yaw)*d[0]-Math.sin(yaw)*d[2],z=Math.sin(yaw)*d[0]+Math.cos(yaw)*d[2];return[x,Math.cos(pitch)*d[1]-Math.sin(pitch)*z,Math.sin(pitch)*d[1]+Math.cos(pitch)*z];}
export function solarFrame(position=[0,0,0],yaw=0,pitch=0,time=0,eye=[0,0,0]){return{axis:local([0,1,0],yaw,pitch),bodies:solarSnapshot(time).map(b=>({...b,center:local(b.position.map((x,i)=>x-position[i]),yaw,pitch),velocity:local(b.velocity,yaw,pitch),cameraCenter:local(b.position.map((x,i)=>x-position[i]),yaw,pitch).map((x,i)=>x-eye[i])}))};}
export function solarUniform(frame){const data=new Float32Array(108);frame.bodies.forEach((b,i)=>data.set([...b.center,b.radius,...b.velocity,b.omega,...b.cameraCenter,0],i*12));return data;}
